import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/plan-bounded-tasks.svg",k=JSON.parse('{"title":"Divide agreed scope into verifiable tasks","description":"","frontmatter":{"title":"Divide agreed scope into verifiable tasks"},"headers":[],"relativePath":"workflows/plan-bounded-tasks.md","filePath":"workflows/plan-bounded-tasks.md"}'),r={name:"workflows/plan-bounded-tasks.md"};function n(l,e,d,p,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="divide-agreed-scope-into-verifiable-tasks" tabindex="-1">Divide agreed scope into verifiable tasks <a class="header-anchor" href="#divide-agreed-scope-into-verifiable-tasks" aria-label="Permalink to &quot;Divide agreed scope into verifiable tasks&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/plan-a-project.html">Plan a project or feature</a>.</p><p>The work is understood but too large to execute as one unbounded change.</p><p><strong>Finish with:</strong> Tasks with completion evidence, genuine dependencies, and an explicit execution boundary.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+i+'" alt="Divide agreed scope into verifiable tasks: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/plan-bounded-tasks.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/plan-bounded-tasks.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/plan-bounded-tasks.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. No additional instruction requirement is recorded for these selected steps.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Read agreed scope.</strong> <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> provides the guidance for this step.</li><li><strong>Define bounded outcomes.</strong> <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> provides the guidance for this step.</li><li><strong>Check dependencies.</strong> <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> provides the guidance for this step.</li><li><strong>Hand off the task plan.</strong> <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Planning stops before execution. Delegation is optional and needs separate authorization; a dependency diagram must not manufacture a fixed order.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> when the direction is agreed but observable behavior, acceptance criteria, constraints, or test boundaries remain unclear.</li><li>Choose <a href="/projects/ai-skills/skills/background-agents.html"><code>background-agents</code></a> when you authorize background workers for substantial work while keeping the main conversation available.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const f=a(r,[["render",n]]);export{k as __pageData,f as default};
